import { describe, it, expect, jest, beforeEach, afterEach } from '@jest/globals';
import { BaseService, ServiceDependencies } from '../../src/services/base/BaseService';
import { CurriculumImportService } from '../../src/services/curriculumImportService';
import { ClusteringService } from '../../src/services/clusteringService';
import { EmbeddingService } from '../../src/services/embeddingService';
import { createMockDependencies } from '../utils/createServiceMocks';

describe('BaseService DI Verification', () => {
  describe('Real Implementation Compatibility', () => {
    it('should create services without dependencies (backward compatibility)', () => {
      // These should use real dependencies
      expect(() => new CurriculumImportService()).not.toThrow();
      expect(() => new ClusteringService()).not.toThrow();
      expect(() => new EmbeddingService()).not.toThrow();
    });

    it('should create services with mock dependencies', () => {
      const mockDeps = createMockDependencies(jest);
      
      // These should use mock dependencies
      expect(() => new CurriculumImportService(mockDeps)).not.toThrow();
      expect(() => new ClusteringService(mockDeps)).not.toThrow();
      expect(() => new EmbeddingService(mockDeps)).not.toThrow();
    });

    it('should properly use injected dependencies', () => {
      const mockDeps = createMockDependencies(jest);
      
      // Create service with mocks
      const service = new CurriculumImportService(mockDeps);
      
      // Access protected properties through any type
      const serviceAny = service as any;
      
      // Verify it's using our injected dependencies
      expect(serviceAny.prisma).toBe(mockDeps.prisma);
      expect(serviceAny.logger).toBe(mockDeps.logger);
      
      // Verify logger is configured correctly
      expect(serviceAny.serviceName).toBe('CurriculumImportService');
    });

    it('should verify all services extend BaseService correctly', () => {
      const mockDeps = createMockDependencies(jest);
      
      const curriculumService = new CurriculumImportService(mockDeps);
      const clusteringService = new ClusteringService(mockDeps);
      const embeddingService = new EmbeddingService(mockDeps);
      
      // All should be instances of BaseService
      expect(curriculumService).toBeInstanceOf(BaseService);
      expect(clusteringService).toBeInstanceOf(BaseService);
      expect(embeddingService).toBeInstanceOf(BaseService);
      
      // All should have proper service names
      expect((curriculumService as any).serviceName).toBe('CurriculumImportService');
      expect((clusteringService as any).serviceName).toBe('ClusteringService');
      expect((embeddingService as any).serviceName).toBe('EmbeddingService');
    });

    it('should maintain isolation between service instances', () => {
      const mockDeps1 = createMockDependencies(jest);
      const mockDeps2 = createMockDependencies(jest);
      
      const service1 = new CurriculumImportService(mockDeps1);
      const service2 = new CurriculumImportService(mockDeps2);
      
      // They should have different mock instances
      expect((service1 as any).prisma).not.toBe((service2 as any).prisma);
      expect((service1 as any).logger).not.toBe((service2 as any).logger);
    });
  });

  describe('Mock Functionality Verification', () => {
    it('should verify mock prisma transaction behavior', async () => {
      const mockDeps = createMockDependencies(jest);
      const mockPrisma = mockDeps.prisma as any;
      
      // Setup mock return value
      const expectedResult = { id: 'test-123', data: 'test' };
      
      // Test transaction with callback
      const result = await mockPrisma.$transaction(async (tx: any) => {
        return expectedResult;
      });
      
      expect(result).toEqual(expectedResult);
      expect(mockPrisma.$transaction).toHaveBeenCalledTimes(1);
    });

    it('should verify mock logger behavior', () => {
      const mockDeps = createMockDependencies(jest);
      const mockLogger = mockDeps.logger as any;
      
      // Test logger methods
      mockLogger.info('test info');
      mockLogger.error('test error');
      mockLogger.warn('test warning');
      
      expect(mockLogger.info).toHaveBeenCalledWith('test info');
      expect(mockLogger.error).toHaveBeenCalledWith('test error');
      expect(mockLogger.warn).toHaveBeenCalledWith('test warning');
      
      // Test child logger returns self
      const childLogger = mockLogger.child({ component: 'test' });
      expect(childLogger).toBe(mockLogger);
    });

    it('should verify mock prisma model operations', async () => {
      const mockDeps = createMockDependencies(jest);
      const mockPrisma = mockDeps.prisma as any;
      
      // Setup mock data
      const testExpectation = {
        id: 'exp-123',
        description: 'Test expectation',
        grade: 5,
      };
      
      mockPrisma.curriculumExpectation.create.mockResolvedValue(testExpectation);
      mockPrisma.curriculumExpectation.findMany.mockResolvedValue([testExpectation]);
      
      // Test operations
      const created = await mockPrisma.curriculumExpectation.create({
        data: { description: 'Test expectation', grade: 5 },
      });
      
      const found = await mockPrisma.curriculumExpectation.findMany({
        where: { grade: 5 },
      });
      
      expect(created).toEqual(testExpectation);
      expect(found).toEqual([testExpectation]);
      expect(mockPrisma.curriculumExpectation.create).toHaveBeenCalledTimes(1);
      expect(mockPrisma.curriculumExpectation.findMany).toHaveBeenCalledTimes(1);
    });
  });
});